CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS app;
CREATE OR REPLACE FUNCTION app.current_organization_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('app.organization_id', true), '')::uuid $$;
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9-]{3,63}$'), name text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 160), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK (email = lower(email)), display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 2 AND 160), password_hash text NOT NULL, is_platform_admin boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL);
CREATE TABLE permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE);
CREATE TABLE role_permissions (role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id));
CREATE TABLE membership_roles (membership_id uuid NOT NULL REFERENCES memberships(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id), PRIMARY KEY(membership_id,role_id));
CREATE TABLE departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,code), UNIQUE(organization_id,id));
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,code), UNIQUE(organization_id,id));
CREATE TABLE disciplines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,code), UNIQUE(organization_id,id));
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,code), UNIQUE(organization_id,id));
CREATE TABLE subcategories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, category_id uuid NOT NULL, code text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,category_id) REFERENCES categories(organization_id,id) ON DELETE CASCADE, UNIQUE(organization_id,code));
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES organizations(id) ON DELETE SET NULL, actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, target_type text NOT NULL, target_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE ROLE jupiter_app NOLOGIN;
GRANT USAGE ON SCHEMA public, app TO jupiter_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO jupiter_app;
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY; ALTER TABLE membership_roles ENABLE ROW LEVEL SECURITY; ALTER TABLE departments ENABLE ROW LEVEL SECURITY; ALTER TABLE locations ENABLE ROW LEVEL SECURITY; ALTER TABLE disciplines ENABLE ROW LEVEL SECURITY; ALTER TABLE categories ENABLE ROW LEVEL SECURITY; ALTER TABLE subcategories ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY memberships_tenant ON memberships USING (organization_id=app.current_organization_id()) WITH CHECK (organization_id=app.current_organization_id());
CREATE POLICY membership_roles_tenant ON membership_roles USING (membership_id IN (SELECT id FROM memberships)) WITH CHECK (membership_id IN (SELECT id FROM memberships));
CREATE POLICY departments_tenant ON departments USING (organization_id=app.current_organization_id()) WITH CHECK (organization_id=app.current_organization_id()); CREATE POLICY locations_tenant ON locations USING (organization_id=app.current_organization_id()) WITH CHECK (organization_id=app.current_organization_id()); CREATE POLICY disciplines_tenant ON disciplines USING (organization_id=app.current_organization_id()) WITH CHECK (organization_id=app.current_organization_id()); CREATE POLICY categories_tenant ON categories USING (organization_id=app.current_organization_id()) WITH CHECK (organization_id=app.current_organization_id()); CREATE POLICY subcategories_tenant ON subcategories USING (organization_id=app.current_organization_id()) WITH CHECK (organization_id=app.current_organization_id()); CREATE POLICY audit_logs_tenant ON audit_logs USING (organization_id=app.current_organization_id()) WITH CHECK (organization_id=app.current_organization_id());
INSERT INTO roles(code,name) VALUES ('ORG_ADMIN','Organization administrator'),('SUPERVISOR','Supervisor'),('EXPERT','Expert'),('REQUESTER','Requester') ON CONFLICT DO NOTHING;
INSERT INTO permissions(code) VALUES ('organization:read'),('organization:manage'),('membership:read'),('membership:manage'),('directory:read'),('directory:manage') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='ORG_ADMIN' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN ('organization:read','membership:read','directory:read') WHERE r.code IN ('SUPERVISOR','EXPERT','REQUESTER') ON CONFLICT DO NOTHING;
